pub(super) fn create() -> Vec<DemonMeta> {
    DEMONS
        .iter()
        .map(|record| {
            let start = record.natural_skill_start;
            let end = start + record.natural_skill_len;

            DemonMeta {
                id: record.id,
                race: record.race,
                base_level: record.base_level,
                content: record.content,
                compendium_price: record.compendium_price,
                natural_skills: NATURAL_SKILLS[start..end].to_vec(),
                innate_skill: record.innate_skill,
            }
        })
        .collect()
}
